import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';
import { Market, TradingHouse } from '@/types/TradingHouseType';
import { apiRequest } from './request';

export async function getHouses(): Promise<TradingHouse[]> {
  if (USE_SEED_DATA) return seed.getHouses();

  const json = await apiRequest<{ result: TradingHouse[] }>(URLS.GET_HOUSES);
  return json.result;
}

export async function getHouseById(id: string): Promise<TradingHouse> {
  if (USE_SEED_DATA) return seed.getHouseById(id);

  const json = await apiRequest<{ result: TradingHouse }>(
    `${URLS.GET_HOUSES}/${id}`,
  );
  return json.result;
}

export async function getMarkets(): Promise<Market[]> {
  if (USE_SEED_DATA) return seed.getMarkets();

  const json = await apiRequest<{ result: Market[] }>(URLS.GET_MARKETS);
  return json.result;
}
