'use client';

import { create } from 'zustand';
import { data } from '@/data';
import { InvestmentLevel } from '@/types/LevelType';

type LevelsStoreType = {
  levels: InvestmentLevel[];
  load: () => Promise<void>;
};

export const useLevelsStore = create<LevelsStoreType>((set, get) => ({
  levels: [],
  load: async () => {
    if (get().levels.length > 0) return;
    const levels = await data.getLevels().catch(() => []);
    set({ levels });
  },
}));
