import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';
import { InvestmentLevel, UserLevelStatus } from '@/types/LevelType';
import { apiRequest } from './request';

export async function getLevels(): Promise<InvestmentLevel[]> {
  if (USE_SEED_DATA) return seed.getLevels();

  const json = await apiRequest<{ result: InvestmentLevel[] }>(URLS.LEVELS);
  return json.result;
}

export async function getLevelStatus(): Promise<UserLevelStatus | null> {
  if (USE_SEED_DATA) return seed.getLevelStatus();

  const json = await apiRequest<{ result: UserLevelStatus }>(URLS.USER_LEVEL);
  return json.result;
}
